import os

def dosya_oku(dosya_adi):
    base_dir = os.path.abspath('/var/www/html/images/')
    tam_yol = os.path.abspath(os.path.join(base_dir, dosya_adi))
    if not tam_yol.startswith(base_dir + os.sep):
        raise ValueError('Geçersiz dosya yolu erişimi!')
    with open(tam_yol, 'r') as f:
        return f.read()
